    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Test helpers ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    fn make_instr(addr: u64, mnemonic: &str) -> Instruction {
        let mut i = Instruction::new(Address::new(addr), 4, mnemonic.to_string(), vec![0x00; 4]);
        i.flags = InstrFlags::NONE;
        i
    }

    /// `LB`/`LH`/`LW` sign-extend the loaded value; `LBU`/`LHU`/`LWU`
    /// zero-extend it. Fourth architecture with this defect after RISC-V, WASM
    /// and the MIPS signed/unsigned compare collapse.
    ///
    /// The rule is `size < register width`, not "signed": `LW` into a 32-bit
    /// register fills it exactly and needs no extension, while the same `LW`
    /// into a 64-bit register does. Both halves asserted, because a fix that
    /// extended on MIPS32 too would be a new defect — and the first attempt
    /// here did exactly that, caught by `test_lift_lw`.
    /// `MULT`/`MULTU` place only the LOW 32 BITS of the product in LO; the high
    /// half belongs to HI, which this lifter models as `Undef`. Writing the
    /// untruncated `Mul` claimed LO held the whole product, and because HI is
    /// opaque the overstatement was unrecoverable downstream.
    ///
    /// Fourth instance of the width class this session, after RISC-V `addw`,
    /// MIPS `add`/`dadd` and BPF ALU32.
    /// A VARIABLE shift takes its count from a REGISTER, and MIPS reads only
    /// the low bits: `rs[4:0]` for the 32-bit forms, `rs[5:0]` for the 64-bit
    /// `D` forms. The count was passed through unmasked, so a register holding
    /// 33 shifted by 33 in the IL and by 1 on the machine.
    ///
    /// The IMMEDIATE forms are deliberately NOT masked: their `sa` field is
    /// five bits wide in the encoding, so it cannot be out of range. Asserting
    /// that too, because masking them would be a new defect rather than extra
    /// safety — and PowerPC is left alone entirely, its rule being different
    /// (a count >= 32 yields zero there instead of wrapping).
    /// `EXT` and `INS` write a value the IR can express in full, but wrote
    /// `Undef` beside an intrinsic naming the operation.
    ///
    /// The marker kept the fact readable, so this was not opacity — every
    /// dataflow pass saw the destination become UNKNOWN when the result is
    /// plain shift-and-mask arithmetic. Same shape as the ARM predication fix:
    /// a marker is not enough when the fact is also EXPRESSIBLE.
    ///
    /// `INS` additionally READS its destination (it merges a field into it),
    /// which the `Undef` form hid completely.
    #[test]
    fn bitfield_ops_are_expressed_not_left_undefined() {
        let l = MipsLifter::new();
        let render = |mnem: &str| {
            let mut i = make_instr(0x1000, mnem);
            i.operand_list = vec![
                reg_operand("t0"),
                reg_operand("t1"),
                rustre_core::arch::Operand::Immediate(4),
                rustre_core::arch::Operand::Immediate(8),
            ];
            format!("{:?}", l.lift(&i).unwrap().effects)
        };

        let ext = render("ext");
        assert!(!ext.contains("Undef"), "ext must compute its value: {ext}");
        assert!(
            ext.contains("Shr") && ext.contains("And"),
            "ext is (rs >> pos) & mask: {ext}"
        );

        let ins = render("ins");
        assert!(!ins.contains("Undef"), "ins must compute its value: {ins}");
        assert!(
            ins.contains("Reg(\"t0\")"),
            "ins merges INTO the destination, so it must read t0: {ins}"
        );
        assert!(ins.contains("Or"), "ins is a mask-and-merge: {ins}");

        // The 64-bit variants adjust pos/size by 32 depending on the encoding;
        // that is deliberately left opaque rather than modelled on a guess.
        let dext = render("dext");
        assert!(
            dext.contains("Undef"),
            "the D variants stay opaque on purpose: {dext}"
        );
    }

    /// `MUL rd, rs, rt` is the MIPS32r2 three-operand multiply: a 32-BIT
    /// operation whose result is sign-extended into a 64-bit register on
    /// MIPS64. It emitted a bare `Mul`, so on the 64-bit lifter the full
    /// product survived and the truncation never happened.
    ///
    /// Its neighbours already handled the class — `add`/`sub` through
    /// `lift_rrr_w`, `sll`/`srl` through `lift_shift_imm` — which is exactly
    /// what made the omission invisible.
    #[test]
    fn three_operand_mul_narrows_on_mips64() {
        let render = |l: &MipsLifter| {
            let mut i = make_instr(0x1000, "mul");
            i.operand_list = vec![reg_operand("t0"), reg_operand("t1"), reg_operand("t2")];
            format!("{:?}", l.lift(&i).unwrap().effects)
        };

        let wide = render(&MipsLifter::new_64());
        assert!(
            wide.contains("Sar") && wide.contains("Const(32)"),
            "on MIPS64 `mul` must sign-extend its 32-bit result: {wide}"
        );

        // On a 32-bit lifter the register IS 32 bits, so no extension belongs
        // there — asserting this stops the fix from becoming a new defect.
        let narrow = render(&MipsLifter::new());
        assert!(
            !narrow.contains("Sar"),
            "on MIPS32 `mul` needs no extension: {narrow}"
        );

        // The SAME omission sat in the arms either side of `mul`: `addi`/
        // `addiu` shared a handler with `daddi`/`daddiu`, and `neg`/`negu` had
        // no width-aware path at all. Checking one member of a family is what
        // let them survive, so the whole family is asserted here.
        let narrow_form = |l: &MipsLifter, m: &str, imm: bool| {
            let mut i = make_instr(0x1000, m);
            i.operand_list = if imm {
                vec![
                    reg_operand("t0"),
                    reg_operand("t1"),
                    rustre_core::arch::Operand::Immediate(5),
                ]
            } else {
                vec![reg_operand("t0"), reg_operand("t1")]
            };
            format!("{:?}", l.lift(&i).unwrap().effects)
        };
        let l64 = MipsLifter::new_64();
        let l32 = MipsLifter::new();
        for (m, imm) in [("addi", true), ("addiu", true), ("neg", false), ("negu", false)] {
            let wide = narrow_form(&l64, m, imm);
            assert!(
                wide.contains("Sar") && wide.contains("Const(32)"),
                "on MIPS64 `{m}` is a 32-bit form and must sign-extend: {wide}"
            );
            assert!(
                !narrow_form(&l32, m, imm).contains("Sar"),
                "on MIPS32 `{m}` needs no extension"
            );
        }
        // The `D` immediates are genuinely 64-bit and must NOT be narrowed.
        for m in ["daddi", "daddiu"] {
            let t = narrow_form(&l64, m, true);
            assert!(!t.contains("Sar"), "`{m}` is 64-bit: {t}");
        }

        // `dmult` is the genuinely 64-bit family and must stay full-width.
        let mut d = make_instr(0x1000, "dmult");
        d.operand_list = vec![reg_operand("t1"), reg_operand("t2")];
        let dm = format!("{:?}", MipsLifter::new_64().lift(&d).unwrap().effects);
        assert!(!dm.contains("Const(32)"), "dmult is 64-bit: {dm}");
    }

    #[test]
    fn variable_shift_counts_are_masked() {
        let l = MipsLifter::new_64();
        let render = |mnem: &str| {
            let mut i = make_instr(0x1000, mnem);
            i.operand_list = vec![reg_operand("t0"), reg_operand("t1"), reg_operand("t2")];
            format!("{:?}", l.lift(&i).unwrap().effects)
        };
        for mnem in ["sllv", "srlv", "srav"] {
            let t = render(mnem);
            assert!(
                t.contains("Const(31)"),
                "{mnem} reads rs[4:0]; its count must be masked, got {t}"
            );
        }
        for mnem in ["dsllv", "dsrlv", "dsrav"] {
            let t = render(mnem);
            assert!(
                t.contains("Const(63)"),
                "{mnem} reads rs[5:0]; its count must be masked, got {t}"
            );
        }

        // The immediate form must NOT grow a mask.
        let mut imm = make_instr(0x1000, "sll");
        imm.operand_list = vec![
            reg_operand("t0"),
            reg_operand("t1"),
            rustre_core::arch::Operand::Immediate(2),
        ];
        let text = format!("{:?}", l.lift(&imm).unwrap().effects);
        assert!(
            !text.contains("Const(31)"),
            "sll's sa is an encoded 5-bit field and needs no mask, got {text}"
        );
    }

    #[test]
    fn multiply_narrows_lo_for_the_32_bit_forms_only() {
        let lo_of = |mnem: &str| -> String {
            let mut i = make_instr(0x1000, mnem);
            i.operand_list = vec![reg_operand("a0"), reg_operand("a1")];
            let l = MipsLifter::new_64();
            l.lift(&i)
                .unwrap()
                .effects
                .iter()
                .find_map(|e| match e {
                    Effect::RegWrite { reg, value } if reg == "lo" => Some(format!("{value:?}")),
                    _ => None,
                })
                .unwrap_or_default()
        };

        // 32-bit signed: low 32 bits, sign-extended (the `sext32` idiom).
        let mult = lo_of("mult");
        assert!(
            mult.contains("Sar") && mult.contains("Shl"),
            "MULT must sign-extend the low 32 bits into LO, got {mult}"
        );
        // 32-bit unsigned: low 32 bits, zero-extended.
        let multu = lo_of("multu");
        assert!(
            multu.contains("0xFFFFFFFF") || multu.contains("4294967295"),
            "MULTU must mask LO to 32 bits, got {multu}"
        );
        // The 64-bit forms genuinely put the low 64 bits in LO: no narrowing.
        let dmult = lo_of("dmult");
        assert!(
            dmult.starts_with("Mul("),
            "DMULT must NOT narrow LO, got {dmult}"
        );

        // And the three must be mutually distinguishable.
        assert_ne!(mult, multu, "MULT and MULTU differ in the extension");
        assert_ne!(mult, dmult, "MULT and DMULT differ in width");
    }

    #[test]
    fn loads_extend_only_when_narrower_than_the_register() {
        let mut lb = make_instr(0x1000, "lb");
        lb.operand_list = vec![reg_operand("v0"), mem_operand("sp", 8)];
        let mut lbu = make_instr(0x1004, "lbu");
        lbu.operand_list = vec![reg_operand("v0"), mem_operand("sp", 8)];
        let mut lw = make_instr(0x1008, "lw");
        lw.operand_list = vec![reg_operand("v0"), mem_operand("sp", 8)];

        let l32 = MipsLifter::new();
        let r = |l: &MipsLifter, i: &Instruction| format!("{:?}", l.lift(i).unwrap().effects);

        // A byte is narrower than a 32-bit register: signed and unsigned differ.
        assert_ne!(r(&l32, &lb), r(&l32, &lbu), "LB and LBU must differ");
        assert!(r(&l32, &lb).contains("sext8"), "LB must sign-extend");

        // The ACCESS SIZE must come from the mnemonic. This test originally
        // checked only the marker, so it passed while `lb` emitted a FOUR-byte
        // read (the memory operand's `width` field was overriding the mnemonic)
        // followed by `sext8` — a read and an extension disagreeing about what
        // was loaded. Checking only the marker is the too-narrow-test failure
        // this session documented; asserting the size closes it.
        let size_of = |l: &MipsLifter, i: &Instruction| {
            l.lift(i).unwrap().effects.iter().find_map(|e| match e {
                Effect::MemRead { size, .. } => Some(*size),
                _ => None,
            })
        };
        assert_eq!(size_of(&l32, &lb), Some(1), "LB reads exactly one byte");
        assert_eq!(size_of(&l32, &lw), Some(4), "LW reads exactly four bytes");

        // Stores take their size from the mnemonic for the same reason. Fixing
        // only the load left `lift_store`/`lift_ll`/`lift_sc` still reading the
        // operand's `width` override, so this direction is asserted too: a fix
        // aimed at one call site does not reach its neighbours.
        let store_size = |l: &MipsLifter, i: &Instruction| {
            l.lift(i).unwrap().effects.iter().find_map(|e| match e {
                Effect::MemWrite { size, .. } => Some(*size),
                _ => None,
            })
        };
        let mut sb = make_instr(0x100c, "sb");
        sb.operand_list = vec![reg_operand("v0"), mem_operand("sp", 8)];
        let mut sw = make_instr(0x1010, "sw");
        sw.operand_list = vec![reg_operand("v0"), mem_operand("sp", 8)];
        assert_eq!(store_size(&l32, &sb), Some(1), "SB writes exactly one byte");
        assert_eq!(store_size(&l32, &sw), Some(4), "SW writes exactly four bytes");
        // A word fills a 32-bit register exactly: nothing to extend.
        assert!(!r(&l32, &lw).contains("sext"), "LW on MIPS32 must not extend");
        // The same word in a 64-bit register does need extending.
        let l64 = MipsLifter::new_64();
        assert!(r(&l64, &lw).contains("sext32"), "LW on MIPS64 must sign-extend");
    }

    /// MIPS64 defines `ADD`/`ADDU`/`SUB`/`SUBU` as 32-BIT operations whose
    /// result is SIGN-EXTENDED into the 64-bit register, while
    /// `DADD`/`DADDU`/`DSUB`/`DSUBU` are the true 64-bit forms. All four shared
    /// one handler, so on a 64-bit lifter the upper half was wrong for every
    /// negative 32-bit result.
    ///
    /// The MIPS32 half is asserted too: there is no upper half to extend into,
    /// so a fix that also "corrected" the 32-bit lifter would be a new defect.
    #[test]
    fn addu_sign_extends_on_mips64_but_not_on_mips32() {
        let mut narrow = make_instr(0x1000, "addu");
        narrow.operand_list = vec![reg_operand("t0"), reg_operand("t1"), reg_operand("t2")];
        let mut wide = make_instr(0x1004, "daddu");
        wide.operand_list = vec![reg_operand("t0"), reg_operand("t1"), reg_operand("t2")];

        let l64 = MipsLifter::new_64();
        let n64 = format!("{:?}", l64.lift(&narrow).unwrap().effects);
        let w64 = format!("{:?}", l64.lift(&wide).unwrap().effects);
        assert_ne!(n64, w64, "on MIPS64, ADDU must sign-extend and DADDU must not");

        let l32 = MipsLifter::new();
        let n32 = format!("{:?}", l32.lift(&narrow).unwrap().effects);
        assert!(!n32.contains("Sar"), "on MIPS32 there is no upper half: {n32}");
    }

    fn reg_operand(name: &str) -> Operand {
        Operand::Register(RegisterInfo::new(name, 0, 4, RegisterKind::General))
    }

    fn imm_operand(v: i64) -> Operand {
        Operand::Immediate(v)
    }

    fn mem_operand(base: &str, disp: i64) -> Operand {
        Operand::Memory {
            base: Some(RegisterInfo::new(base, 0, 4, RegisterKind::General)),
            index: None,
            scale: 1,
            disp,
            width: 4,
        }
    }

    fn label_operand(addr: u64) -> Operand {
        Operand::Label(addr)
    }

