    #[test]
    fn test_lift_nop() {
        let lifter = MipsLifter::new();
        let instr = make_instr(0x4000, "nop");
        let li = lifter.lift(&instr).unwrap();
        assert!(li.effects.is_empty(), "NOP should have no effects");
        assert_eq!(li.ir_text, "nop");
        assert_eq!(li.il_level, LiftLevel::Llil);
        assert_eq!(li.address, 0x4000);
    }

