    #[test]
    fn test_lift_add_r_type() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4000, "add");
        // add $t0, $t1, $t2
        instr.operand_list = vec![reg_operand("t0"), reg_operand("t1"), reg_operand("t2")];
        let li = lifter.lift(&instr).unwrap();
        assert_eq!(li.effects.len(), 1);
        if let Effect::RegWrite { reg, value } = &li.effects[0] {
            assert_eq!(reg, "t0");
            assert!(matches!(value, IrExpr::Add(_, _)));
        } else {
            panic!("expected RegWrite, got {:?}", li.effects[0]);
        }
    }

    #[test]
    fn test_lift_addu_normalises_zero() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4000, "addu");
        // addu $zero, $t1, $t2 ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â write to $zero should be elided.
        instr.operand_list = vec![reg_operand("zero"), reg_operand("t1"), reg_operand("t2")];
        let li = lifter.lift(&instr).unwrap();
        assert!(li.effects.is_empty(), "write to $zero must be elided");
    }

