    #[test]
    fn test_lift_sw() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x400c, "sw");
        // sw $ra, -4($sp)
        instr.operand_list = vec![reg_operand("ra"), mem_operand("sp", -4)];
        let li = lifter.lift(&instr).unwrap();
        assert_eq!(li.effects.len(), 1);
        if let Effect::MemWrite { addr, value, size } = &li.effects[0] {
            assert_eq!(*size, 4);
            assert!(matches!(value, IrExpr::Reg(r) if r == "ra"));
            assert!(matches!(addr, IrExpr::Sub(_, _)));
        } else {
            panic!("expected MemWrite, got {:?}", li.effects[0]);
        }
    }

