    #[test]
    fn test_lift_beq() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4010, "beq");
        // beq $t0, $zero, 0x4020
        instr.operand_list = vec![
            reg_operand("t0"),
            reg_operand("zero"),
            label_operand(0x4020),
        ];
        let li = lifter.lift(&instr).unwrap();
        // Expect a Branch effect + delay_slot intrinsic.
        let branch = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Branch { .. }));
        assert!(branch.is_some(), "BEQ must produce a Branch effect");
        if let Some(Effect::Branch { target, condition }) = branch {
            assert!(condition.is_some(), "BEQ must have a condition");
            assert!(matches!(target, IrExpr::Const(0x4020)));
        }
        // Delay slot annotation.
        let ds = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Intrinsic { name, .. } if name == "delay_slot"));
        assert!(ds.is_some(), "BEQ must annotate its delay slot");
    }

    #[test]
    fn test_lift_bne() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4010, "bne");
        instr.operand_list = vec![reg_operand("t0"), reg_operand("t1"), label_operand(0x4030)];
        let li = lifter.lift(&instr).unwrap();
        let branch = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Branch { .. }));
        assert!(branch.is_some());
        if let Some(Effect::Branch { condition, .. }) = branch {
            assert!(condition.is_some());
            // Condition for BNE is NOT(CmpEqZero(...)).
            assert!(matches!(condition.as_ref().unwrap(), IrExpr::Not(_)));
        }
    }

