    #[test]
    fn test_lift_jr_non_ra_is_branch() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4014, "jr");
        instr.operand_list = vec![reg_operand("t9")];
        let li = lifter.lift(&instr).unwrap();
        let branch = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Branch { .. }));
        assert!(branch.is_some(), "JR $t9 must be a Branch effect");
        if let Some(Effect::Branch { condition, target }) = branch {
            assert!(condition.is_none(), "JR is unconditional");
            assert!(matches!(target, IrExpr::Reg(r) if r == "t9"));
        }
    }

