    #[test]
    fn test_lift_nor() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4024, "nor");
        // nor $t0, $t1, $zero  (effectively NOT $t1)
        instr.operand_list = vec![reg_operand("t0"), reg_operand("t1"), reg_operand("zero")];
        let li = lifter.lift(&instr).unwrap();
        assert_eq!(li.effects.len(), 1);
        if let Effect::RegWrite { value, .. } = &li.effects[0] {
            assert!(
                matches!(value, IrExpr::Not(_)),
                "NOR result must be Not(Or(...))"
            );
        }
    }

