    #[test]
    fn test_lift_sll() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4028, "sll");
        // sll $t0, $t1, 2
        instr.operand_list = vec![reg_operand("t0"), reg_operand("t1"), imm_operand(2)];
        let li = lifter.lift(&instr).unwrap();
        if let Effect::RegWrite { value, .. } = &li.effects[0] {
            assert!(matches!(value, IrExpr::Shl(_, _)));
        }
    }

