    #[test]
    fn test_lift_bgez() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4040, "bgez");
        instr.operand_list = vec![reg_operand("s0"), label_operand(0x4080)];
        let li = lifter.lift(&instr).unwrap();
        let branch = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Branch { .. }));
        assert!(branch.is_some());
        if let Some(Effect::Branch { condition, .. }) = branch {
            assert!(condition.is_some(), "BGEZ must be conditional");
        }
    }

    #[test]
    fn test_lift_bltz() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4044, "bltz");
        instr.operand_list = vec![reg_operand("s1"), label_operand(0x4090)];
        let li = lifter.lift(&instr).unwrap();
        let branch = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Branch { .. }));
        assert!(branch.is_some());
    }

