    #[test]
    fn test_tokenise_operands_simple() {
        let toks = MipsLifter::tokenise_operands("$t0, $t1, $t2");
        assert_eq!(toks, vec!["$t0", "$t1", "$t2"]);
    }

    #[test]
    fn test_tokenise_operands_mem() {
        let toks = MipsLifter::tokenise_operands("$v0, 8($sp)");
        assert_eq!(toks, vec!["$v0", "8($sp)"]);
    }

    #[test]
    fn test_parse_mem_ref_positive() {
        let addr = MipsLifter::parse_mem_ref("16($sp)");
        assert!(matches!(addr, IrExpr::Add(_, _)));
    }

    #[test]
    fn test_parse_mem_ref_negative() {
        let addr = MipsLifter::parse_mem_ref("-8($fp)");
        assert!(matches!(addr, IrExpr::Sub(_, _)));
    }

    #[test]
    fn test_parse_mem_ref_zero() {
        let addr = MipsLifter::parse_mem_ref("0($a0)");
        // zero displacement ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ just the base register.
        assert!(matches!(addr, IrExpr::Reg(r) if r == "a0"));
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Unknown mnemonic ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ Intrinsic ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    #[test]
    fn test_unknown_mnemonic_becomes_intrinsic() {
        let lifter = MipsLifter::new();
        let instr = make_instr(0x4050, "totally_unknown_mips_op");
        let li = lifter.lift(&instr).unwrap();
        let found_intrinsic = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Intrinsic { .. }));
        assert!(
            found_intrinsic.is_some(),
            "unknown mnemonic must fall back to Intrinsic"
        );
    }

