    #[test]
    fn test_lift_jalr_two_operands() {
        let lifter = MipsLifter::new();
        let mut instr = make_instr(0x4054, "jalr");
        // jalr $ra, $t9
        instr.operand_list = vec![reg_operand("ra"), reg_operand("t9")];
        let li = lifter.lift(&instr).unwrap();
        let call = li.effects.iter().find(|e| matches!(e, Effect::Call { .. }));
        assert!(call.is_some(), "JALR must produce a Call");
        let ra_write = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::RegWrite { reg, .. } if reg == "ra"));
        assert!(ra_write.is_some(), "JALR must save $ra");
    }

